// Bitrix24 sends the deal ID in a few different shapes depending on how the
// outbound webhook was configured, so try all of them.
const body = $input.first().json.body || $input.first().json || {};

const dealId =
  (body.data && body.data.FIELDS && body.data.FIELDS.ID) ||
  (body.FIELDS && body.FIELDS.ID) ||
  body['data[FIELDS][ID]'] ||
  body.dealId ||
  body.ID ||
  '';

if (!dealId) {
  throw new Error('Deal ID not found in webhook payload: ' + JSON.stringify(body));
}

return [{ json: { dealId: String(dealId).trim() } }];

// Decides whether this deal should be uploaded to Google Ads.
const S = $('Settings').first().json;
const deal = $input.first().json.result || {};

const dealId = String(deal.ID || '').trim();
if (!dealId) {
  return [{ json: { shouldSend: false, skipReason: 'missing_deal_id' } }];
}

// Values read from your own Bitrix24 custom fields (configured in Settings).
const gclid = String(deal[S.gclidFieldId] || '').trim();
const qualifiedRaw = deal[S.qualifiedFieldId];
const isQualified = Array.isArray(qualifiedRaw)
  ? qualifiedRaw.map(String).includes(String(S.qualifiedValue))
  : String(qualifiedRaw) === String(S.qualifiedValue);
const alreadySent = String(deal[S.sentFlagFieldId] || '') === '1';

// Bitrix24 often fires several identical events for one change. Keep a short
// in-memory record of recently seen deals so we do not upload duplicates.
const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const DEDUPE_TTL_MS = 2 * 60 * 1000;
const key = 'ga_upload_guard_' + dealId;

for (const [k, v] of Object.entries(staticData)) {
  if (k.startsWith('ga_upload_guard_') && (typeof v !== 'number' || now - v > DEDUPE_TTL_MS)) {
    delete staticData[k];
  }
}
const dedupeHit = typeof staticData[key] === 'number' && now - staticData[key] < DEDUPE_TTL_MS;

// Allow a manual re-send by posting { "manualRetry": true } to the webhook.
const webhookBody = $('Bitrix24 Deal Webhook').first().json.body || {};
const manualRetry = webhookBody.manualRetry === true || String(webhookBody.manualRetry || '').toLowerCase() === 'true';

let skipReason = null;
if (!gclid) skipReason = 'missing_gclid';
else if (!isQualified) skipReason = 'not_qualified';
else if (!manualRetry && alreadySent) skipReason = 'already_sent';
else if (!manualRetry && dedupeHit) skipReason = 'duplicate_event';

if (!skipReason) staticData[key] = now;

// Google Ads expects "YYYY-MM-DD HH:MM:SS+|-HH:MM".
const raw = deal.DATE_MODIFY || deal.DATE_CREATE || new Date().toISOString();
const d = new Date(raw);
const p = (n) => String(n).padStart(2, '0');
const conversionDateTime =
  d.getUTCFullYear() + '-' + p(d.getUTCMonth() + 1) + '-' + p(d.getUTCDate()) + ' ' +
  p(d.getUTCHours()) + ':' + p(d.getUTCMinutes()) + ':' + p(d.getUTCSeconds()) + '+00:00';

const value = Number.parseFloat(deal.OPPORTUNITY || 0);

return [{
  json: {
    shouldSend: !skipReason,
    skipReason,
    dealId,
    gclid,
    contactId: String(deal.CONTACT_ID || '').trim(),
    conversionValue: Number.isFinite(value) ? value : 0,
    currency: deal.CURRENCY_ID || S.fallbackCurrency,
    conversionDateTime,
  },
}];

// Normalises customer data exactly as Google Ads requires before hashing:
// lower-cased trimmed email (with gmail dot/plus rules), E.164 phone,
// lower-cased names, ISO-3166-1 alpha-2 country.
const source = $('Check Eligibility').first().json;
const contact = ($input.first().json && $input.first().json.result) || {};

function firstValue(list) {
  if (!Array.isArray(list)) return '';
  for (const item of list) {
    const v = String((item && item.VALUE) || '').trim();
    if (v) return v;
  }
  return '';
}

function normalizeEmail(input) {
  const value = String(input || '').trim().toLowerCase();
  const parts = value.split('@');
  if (parts.length !== 2 || !parts[0] || !parts[1]) return '';
  let [local, domain] = parts;
  if (domain === 'gmail.com' || domain === 'googlemail.com') {
    local = local.split('+')[0].replace(/\./g, '');
  }
  return local + '@' + domain;
}

function normalizePhone(input) {
  let value = String(input || '').replace(/[^\d+]/g, '');
  if (value.startsWith('00')) value = '+' + value.slice(2);
  value = '+' + value.replace(/\D/g, '');
  return value.length < 9 ? '' : value;
}

function toIso2(input) {
  const value = String(input || '').trim();
  if (/^[A-Za-z]{2}$/.test(value)) return value.toUpperCase();
  // Extend this map with the country names your CRM actually stores.
  const map = {
    'united states': 'US', usa: 'US', 'united kingdom': 'GB', uk: 'GB',
    canada: 'CA', germany: 'DE', france: 'FR', spain: 'ES', italy: 'IT',
    netherlands: 'NL', poland: 'PL', india: 'IN', australia: 'AU', brazil: 'BR',
  };
  return map[value.toLowerCase()] || '';
}

return [{
  json: {
    dealId: source.dealId,
    gclid: source.gclid,
    conversionValue: source.conversionValue,
    currency: source.currency,
    conversionDateTime: source.conversionDateTime,
    normalizedEmail: normalizeEmail(firstValue(contact.EMAIL)),
    normalizedPhone: normalizePhone(firstValue(contact.PHONE)),
    normalizedFirstName: String(contact.NAME || '').trim().toLowerCase(),
    normalizedLastName: String(contact.LAST_NAME || '').trim().toLowerCase(),
    countryCode: toIso2(contact.ADDRESS_COUNTRY),
    postalCode: String(contact.ADDRESS_POSTAL_CODE || '').trim().toUpperCase().replace(/\s+/g, ' '),
  },
}];

// Assembles the ClickConversion payload. Hashed identifiers are only attached
// when the underlying value actually existed, so we never send a hash of "".
const S = $('Settings').first().json;
const j = $input.first().json;

const conversion = {
  gclid: j.gclid,
  conversionAction: 'customers/' + S.googleAdsCustomerId + '/conversionActions/' + S.conversionActionId,
  conversionDateTime: j.conversionDateTime,
  orderId: j.dealId,
  currencyCode: j.currency || S.fallbackCurrency,
  conversionValue: j.conversionValue,
};

const userIdentifiers = [];
if (j.normalizedEmail) {
  userIdentifiers.push({ userIdentifierSource: 'FIRST_PARTY', hashedEmail: j.hashedEmail });
}
if (j.normalizedPhone) {
  userIdentifiers.push({ userIdentifierSource: 'FIRST_PARTY', hashedPhoneNumber: j.hashedPhone });
}
if (j.normalizedFirstName && j.normalizedLastName && j.countryCode && j.postalCode) {
  userIdentifiers.push({
    userIdentifierSource: 'FIRST_PARTY',
    addressInfo: {
      hashedFirstName: j.hashedFirstName,
      hashedLastName: j.hashedLastName,
      countryCode: j.countryCode,
      postalCode: j.postalCode,
    },
  });
}
// Google Ads accepts at most 5 user identifiers per conversion.
if (userIdentifiers.length) conversion.userIdentifiers = userIdentifiers.slice(0, 5);

return [{
  json: {
    dealId: j.dealId,
    gclid: j.gclid,
    requestBody: { conversions: [conversion], partialFailure: true },
  },
}];

// Google Ads answers 200 even when a conversion was rejected, so inspect
// partialFailureError instead of trusting the status code.
const payload = $input.first().json || {};
const body = payload.body || payload;

const partialFailure = body.partialFailureError;
const pfStr = partialFailure && Object.keys(partialFailure).length ? JSON.stringify(partialFailure) : '';
const results = Array.isArray(body.results) ? body.results.filter((r) => r && Object.keys(r).length) : [];

// These outcomes mean "already recorded" - treat them as success so the deal
// gets flagged and we stop retrying forever.
const isTerminal = /ALREADY_EXISTS|DUPLICATE|EXPIRED_EVENT/i.test(pfStr);

if (pfStr && !isTerminal) {
  throw new Error('Google Ads partial failure: ' + pfStr);
}
if (!results.length && !pfStr) {
  throw new Error('Google Ads returned no conversion results: ' + JSON.stringify(body));
}

const source = $('Build Conversion Payload').first().json || {};

return [{
  json: {
    uploaded: true,
    dealId: source.dealId || '',
    gclid: source.gclid || '',
    terminalPartialFailure: isTerminal ? pfStr.slice(0, 300) : '',
    uploadedAt: new Date().toISOString(),
  },
}];
